// Builds the base64 watercolour placeholders painted behind the homepage hero.
//
// The hero painting is the LCP element and lands at ~880 ms on a slow
// connection. Until it does there is nothing but paper, so the page reads as
// empty for most of a second. A 32 px-wide crop of the same painting, inlined
// as a data: URI, fills that gap with the painting's own colours for under a
// kilobyte — no request, so it paints with the first frame of CSS.
//
// Generated file: re-run after changing the hero artwork.
// Usage: node scripts/make-lqip.mjs
import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'

// sharp comes with Astro's image pipeline; resolve it the way the build does.
const require = createRequire(import.meta.url)
const sharp = require('sharp')

const root = path.resolve(import.meta.dirname, '..')
const WIDTH = 32

async function placeholder(file) {
  const buffer = await sharp(file).resize({ width: WIDTH }).webp({ quality: 50 }).toBuffer()
  console.log(`  ${path.basename(file)} → ${buffer.length} bytes`)
  return `data:image/webp;base64,${buffer.toString('base64')}`
}

const day = await placeholder(path.join(root, 'src/assets/hero/hero-watercolor.webp'))
const night = await placeholder(path.join(root, 'src/assets/hero/hero-watercolor-night.webp'))

const out = `// Generated by scripts/make-lqip.mjs — do not edit.
// 32 px-wide crops of the hero watercolours, inlined as data: URIs so the
// hero band paints its own colours before the painting arrives.
export default {
  day: '${day}',
  night: '${night}',
} as const
`

const target = path.join(root, 'src/data/hero-lqip.ts')
fs.mkdirSync(path.dirname(target), { recursive: true })
fs.writeFileSync(target, out)
console.log(`wrote ${path.relative(root, target)} (${out.length} bytes)`)
